// FFI surface for CUDA/cuBLAS/FlashInfer kernels, split by owning model.
// Public paths are unchanged: `pegainfer_kernels::ffi::<symbol>` resolves via the re-exports below.

// Half type (16-bit float) - same layout as CUDA half. Shared ABI type used by all submodules.
pub type Half = u16;

#[cfg(feature = "moe")]
mod deepep;
#[cfg(feature = "deepseek-v2-lite")]
mod deepseek_v2_lite;
#[cfg(feature = "gemma4")]
mod gemma4;
#[cfg(feature = "gemma4")]
mod gemma4_tilelang;
#[cfg(feature = "glm52")]
mod glm52;
#[cfg(feature = "k3")]
mod k3;
#[cfg(feature = "k3")]
mod k3_tilelang;
#[cfg(feature = "kimi-k2")]
mod kimi;
mod lora;
#[cfg(feature = "qwen35")]
mod qwen35;
#[cfg(feature = "qwen4")]
mod qwen4;
mod shared;
#[cfg(feature = "moe")]
pub use deepep::*;
#[cfg(feature = "deepseek-v2-lite")]
pub use deepseek_v2_lite::*;
#[cfg(feature = "gemma4")]
pub use gemma4::*;
#[cfg(feature = "gemma4")]
pub use gemma4_tilelang::*;
#[cfg(feature = "glm52")]
pub use glm52::*;
#[cfg(feature = "k3")]
pub use k3::*;
#[cfg(feature = "k3")]
pub use k3_tilelang::*;
#[cfg(feature = "kimi-k2")]
pub use kimi::*;
pub use lora::*;
#[cfg(feature = "qwen4")]
pub use qwen4::*;
#[cfg(feature = "qwen35")]
pub use qwen35::*;
pub use shared::*;

